<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$from=trim((string)($_GET['from']??date('Y-m-01')));$to=trim((string)($_GET['to']??date('Y-m-t')));$p=['rows'=>[],'income'=>0,'expense'=>0,'profit'=>0];$deferred=0;
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$from=finance_step16_date($from,'from date');$to=finance_step16_date($to,'to date');$p=finance_step16_pnl($pdo,$orgId,$from,$to);$stmt=$pdo->prepare("SELECT COUNT(*) FROM product_sale_ledger sl JOIN orders o ON o.id=sl.order_id AND o.organization_id=sl.organization_id WHERE sl.organization_id=? AND sl.sale_status='active' AND sl.cost_status<>'complete' AND o.order_date BETWEEN ? AND ?");$stmt->execute([$orgId,$from,$to]);$deferred=(int)$stmt->fetchColumn();}catch(Throwable $e){$error=$e->getMessage();}
function pl_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function pl_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Profit & Loss - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Profit & Loss</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_monthly.php">Monthly</a><a class="os-btn" href="finance_export.php">Export</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Statements</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a class="active" href="finance_profit_loss.php"><i class="dot"></i>Profit & Loss</a><a href="finance_cash_flow.php"><i class="dot"></i>Cash Flow</a><a href="finance_monthly.php"><i class="dot"></i>Monthly Summary</a><a href="finance_receivable_payable.php"><i class="dot"></i>AR / AP</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 16E • PROFIT & LOSS</div><h1>See ledger-based income, returns, verified COGS and expenses.</h1><p>COGS is posted only when the Product Sale has complete explicit cost coverage. Deferred cost is never guessed.</p></section><section class="os-card" style="margin-top:14px"><form method="get" class="pp-form"><label>From<input type="date" name="from" value="<?= pl_h($from) ?>"></label><label>To<input type="date" name="to" value="<?= pl_h($to) ?>"></label><button>Generate P&amp;L</button></form></section><?php if($error):?><div class="pp-alert bad"><strong>P&amp;L diagnostic:</strong> <?= pl_h($error) ?></div><?php else:?><section class="s10-kpis"><div class="s10-kpi"><small>Net Income</small><strong><?= pl_m($p['income']) ?></strong><span>Income accounts after contra entries</span></div><div class="s10-kpi"><small>Expenses</small><strong><?= pl_m($p['expense']) ?></strong><span>Including verified COGS</span></div><div class="s10-kpi"><small>Net Profit / Loss</small><strong><?= pl_m($p['profit']) ?></strong><span><?= $p['profit']>=0?'Profit':'Loss' ?></span></div><div class="s10-kpi"><small>Deferred-cost Sales</small><strong><?= $deferred ?></strong><span>Excluded from guessed COGS</span></div></section><section class="os-card" style="margin-top:14px"><h2>Statement Detail</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Class</th><th>Code</th><th>Account</th><th>Debits</th><th>Credits</th><th>Net Effect</th></tr></thead><tbody><?php foreach($p['rows'] as $r):?><tr><td><?= pl_h(strtoupper($r['account_class'])) ?></td><td><?= pl_h($r['account_code']) ?></td><td><b><?= pl_h($r['account_name']) ?></b></td><td><?= pl_m($r['debits']) ?></td><td><?= pl_m($r['credits']) ?></td><td><b><?= pl_m($r['net']) ?></b></td></tr><?php endforeach;?><?php if(!$p['rows']):?><tr><td colspan="6">No P&amp;L journal activity in this period.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Statement rule:</strong> Sales Returns is a contra-income account, so its debit balance automatically reduces net income. Tax treatment is not inferred.</div><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
